package com.halloweenmenu.client;

/** Данные сцены: карта глубины и маска ведьмы на сетке 64x36 (сгенерировано). */
final class SceneData {
    static final int GX = 64;
    static final int GY = 36;
    static final String DEPTH = "";
    static final String MASK = "";

    private SceneData() {
    }

    static float[] decode(String hex) {
        float[] out = new float[hex.length() / 2];
        for (int i = 0; i < out.length; i++) {
            out[i] = Integer.parseInt(hex.substring(i * 2, i * 2 + 2), 16) / 255f;
        }
        return out;
    }
}
